import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Button, Form, Select, Alert, Spin, Input } from 'antd'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import QueryString from 'query-string'
import EditTemplateStyled from './editTemplate.style'
import NotificationActions from '../../redux/notifications/actions'
import PolicyActions from '../../../redux/policy/actions'
import TableWrapper from './table.style'
import EditRuleModal from './editRule'
import AddRuleModal from './addRule'
import TagsInput from 'react-tagsinput'

import 'react-tagsinput/react-tagsinput.css'

const {
  getMasterData,
  updateTemplate,
  resetNotificationCore,
  closeViewBodyHtml,
  addTemplate,
  getActionGroup,
  getFilterTriggeredData,
  getTemplates,
  addTrigger,
  resetFilteredData,
  getProduct
} = NotificationActions
const { getProducts, getPartners } = PolicyActions

const FormItem = Form.Item
const Option = Select.Option

class AddTemplate extends React.Component {
  state = {
    htmlContent: '',
    masterData: {},
    queryString: QueryString.parse(this.props.location.search),
    submitting: false,
    actionGroupLoader: false,
    paramsFilterTrigger: {},
    dataFilteredTrigger: [],
    loadingTableTrigger: false,
    masterExpression: [],
    newExpression: [],
    isModalEditRuleOpen: false,
    isModalAddRuleOpen: false,
    disableSubmit: true,
    isDisableInput: false,
    loaderProduct: false,
    fixed_recipients_bcc: [],
    fixed_recipients_cc: [],
    fixed_recipients_to: [],
    reply_to: ''
  }
  componentWillReceiveProps (nextProps) {
    const {
      masterData,
      getMasterDataStatus,
      dataActionGroup,
      getActionGroupStatus,
      dataFilteredTrigger,
      getFilteredTriggerDataStatus,
      getTemplatesStatus,
      dataTemplates,
      addTriggerStatus,
      getProductsByPartnerCodeStatus,
      dataProducts
    } = nextProps.Notifications
    if (getMasterDataStatus !== '') {
      this.setState({ masterData, getMasterDataStatus })
    }
    if (getActionGroupStatus !== '') {
      this.setState({
        dataActionGroup,
        getActionGroupStatus,
        actionGroupLoader: false
      })
    }
    const { products, partners } = nextProps.Policy
    if ((partners !== undefined && partners.length > 0) || (products !== undefined && products.length > 0)) {
      this.setState({ partners, products })
    }
    if (getFilteredTriggerDataStatus !== '' && dataFilteredTrigger === undefined) {
      this.setState({
        dataFilteredTrigger,
        getFilteredTriggerDataStatus,
        loadingTableTrigger: false,
        disableSubmit: true
      })
    }
    if (getFilteredTriggerDataStatus !== '' && dataFilteredTrigger !== undefined) {
      let expression = []
      let count = 0
      dataFilteredTrigger.map((val, index) => {
        let modifyElement = val.expression.map(element => {
          for (let key in element) { // eslint-disable-line
            element['index'] = count++
          }
          return element
        })
        expression = [...expression, ...modifyElement]
        return expression
      })
      this.setState({
        dataFilteredTrigger,
        getFilteredTriggerDataStatus,
        loadingTableTrigger: false,
        disableSubmit: false
      })
    }
    if (getTemplatesStatus !== '') {
      this.setState({ dataTemplates, getTemplatesStatus })
    }
    if (addTriggerStatus !== '') {
      this.setState({ addTriggerStatus, submitting: false })
    }
    if (addTriggerStatus !== '' && addTriggerStatus === 'success') {
      this.setState({ isDisableInput: true })
    }
    if (getProductsByPartnerCodeStatus !== '') {
      this.setState({
        getProductsByPartnerCodeStatus,
        dataProducts,
        loaderProduct: false
      })
    }
  }
  componentDidMount () {
    this.props.getMasterData()
    this.props.getProducts()
    this.props.getPartners()
    this.props.getTemplates()
  }
  componentWillUnmount () {
    this.props.resetNotificationCore()
    this.props.closeViewBodyHtml()
  }
  back = () => {
    const { history } = this.props
    history.push('/notifications')
  }
  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }
  onSubmit = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    this.setState({ submitting: true })
    const { form } = this.props
    const { newExpression, masterExpression } = this.state
    let data = form.getFieldsValue()
    if (newExpression.length === 0) {
      data = { ...data, expression: masterExpression }
    } else {
      const modifyExpression = newExpression.map(val => {
        for (let key in val) { // eslint-disable-line
          delete val['index']
          if (val['op'] === 'gt' || val['op'] === 'gte' || val['op'] === 'lt' || val['op'] === 'lte') {
            val['val'] = parseInt(val['val'])
          }
        }
        return val
      })
      data = { ...data, expression: modifyExpression }
    }
    data = {
      ...data,
      weight: Number(data.weight),
      fixed_recipients_bcc: this.state.fixed_recipients_bcc,
      fixed_recipients_cc: this.state.fixed_recipients_cc,
      fixed_recipients_to: this.state.fixed_recipients_to,
      reply_to: this.state.reply_to
    }
    this.props.addTrigger(data)
  }
  handleEditorChange = (e) => {
    this.setState({ htmlContent: e.target.innerHTML })
  }
  onCloseAlert = () => {
    this.props.resetNotificationCore()
    this.setState({ getFilteredTriggerDataStatus: '' })
  }
  handleChangeEvent = val => {
    this.setState({
      actionGroupLoader: true,
      paramsFilterTrigger: {
        ...this.state.paramsFilterTrigger,
        trigger_type: val
      }
    })
    this.props.getActionGroup({ trigger_type: val })
  }
  handleChangeActionGroup = val => {
    this.setState({
      actionGroup: val,
      paramsFilterTrigger: {
        ...this.state.paramsFilterTrigger,
        action_group: val
      }
    })
  }
  handleChangePartner = val => {
    this.setState({
      partnerValue: val,
      paramsFilterTrigger: {
        ...this.state.paramsFilterTrigger,
        partner_code: val
      },
      loaderProduct: true
    })
    this.props.form.setFieldsValue({
      'product_key': ''
    })
    this.props.getProduct({ partnerCode: val })
  }
  handleChangeProduct = val => {
    this.setState({
      productValue: val,
      paramsFilterTrigger: {
        ...this.state.paramsFilterTrigger,
        product_key: val
      },
      loadingTableTrigger: true,
      getFilteredTriggerDataStatus: undefined
    })
    let data = { ...this.state.paramsFilterTrigger, product_key: val }
    this.props.getFilterTriggeredData(data)
    this.props.resetNotificationCore()
  }
  editRule = rule => {
    this.setState({
      isModalEditRuleOpen: true,
      selectedRule: rule
    })
  }
  closeEditRuleModal = () => {
    this.setState({ isModalEditRuleOpen: false })
  }
  updateNewRule = newRule => {
    let { masterExpression, selectedRule } = this.state
    let duplicate = false
    // masterExpression.map(val => {
    //   for (let key in val) {
    //     if (key === 'op' || key === 'var') {
    //       if (val['op'] === newRule['op'] && val['var'] === newRule['var']) {
    //         duplicate = true
    //         break
    //       }
    //     }
    //   }
    // })
    if (duplicate) {
      alert('selector & operator should be unique!')
      this.setState({ isModalEditRuleOpen: false })
      return
    }
    let indexObject = masterExpression.findIndex(x => {
      return x.op === selectedRule.op && x.val === selectedRule.val && x.var === selectedRule.var
    })
    masterExpression.splice(indexObject, 1)
    masterExpression.unshift(newRule)
    this.setState({
      masterExpression,
      newExpression: masterExpression,
      isModalEditRuleOpen: false
    })
  }
  addRule = () => {
    this.setState({ isModalAddRuleOpen: true })
  }
  closeAddRuleModal = () => {
    this.setState({ isModalAddRuleOpen: false })
  }
  addNewRule = rule => {
    let { masterExpression } = this.state
    let duplicate = false
    masterExpression.forEach(val => {
      for (let key in val) {
        if (key === 'op' || key === 'var') {
          if (val['op'] === rule['op'] && val['var'] === rule['var']) {
            duplicate = true
            break
          }
        }
      }
    })
    if (duplicate) {
      alert('selector & operator should be unique!')
      this.setState({ isModalAddRuleOpen: false })
      return
    }
    masterExpression.unshift(rule)
    this.setState({
      masterExpression,
      newExpression: masterExpression,
      isModalAddRuleOpen: false
    })
  }
  handleChangeTags (tags, identifier) {
    this.setState({
      [identifier]: tags,
      isFilled: {
        ...this.state.isFilled,
        [identifier]: true
      }
    })
  }
  render () {
    const {
      masterData,
      submitting,
      dataActionGroup,
      partners,
      dataFilteredTrigger,
      masterExpression,
      isModalEditRuleOpen,
      dataTemplates,
      isModalAddRuleOpen,
      dataProducts
    } = this.state
    const { form } = this.props
    const { getFieldDecorator } = form
    let expression = []
    if (dataFilteredTrigger !== undefined) {
      dataFilteredTrigger.forEach((val) => {
        expression = [...expression, ...val.expression]
      })
    }
    const columns = [{
      title: 'Description',
      key: '1',
      dataIndex: 'name'
    }, {
      title: 'Expression',
      key: '2',
      render: (text) => {
        return text.expression.map(value => {
          return JSON.stringify(value)
        })
      }
    }, {
      title: 'Template',
      key: '3',
      dataIndex: 'template_code'
    }, {
      title: 'Weight',
      key: '4',
      dataIndex: 'weight'
    }]
    const columnsExpression = [{
      title: 'Selector',
      key: '1',
      dataIndex: 'var',
      render: (itemRecord, record) => {
        return itemRecord + '  '
      }
    }, {
      title: 'Operator',
      key: '2',
      dataIndex: 'op'
    }, {
      title: 'Value',
      key: '3',
      dataIndex: 'val',
      render: (itemRecord, record) => {
        return typeof itemRecord === 'string'
          ? itemRecord
          : itemRecord.map((item) => <div>
            {
              item.map((v) =>
                <span style={{ width: '50%' }}>{v + ' '}</span>)
            }
          </div>
          )
      }
    }, {
      title: 'Action',
      key: '4',
      render: (text, record) => {
        if (!this.state.isDisableInput) {
          return (
            <span>
              <span className='anchor' onClick={() => this.editRule(record)}>Edit</span>
            </span>
          )
        }
      }
    }]
    return (
      <div>
        <LayoutContentWrapper>
          {
            (this.state.addTriggerStatus !== '' && this.state.addTriggerStatus !== undefined && this.state.addTriggerStatus === 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.addTriggerStatus}
                    type={'success'}
                    closable
                    onClose={this.onCloseAlert}
                  />
                </Col>
              </Row>
            )
          }
          {
            (this.state.addTriggerStatus !== '' && this.state.addTriggerStatus !== undefined && this.state.addTriggerStatus !== 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.addTriggerStatus}
                    type={'error'}
                    closable
                    onClose={this.onCloseAlert}
                  />
                </Col>
              </Row>
            )
          }
          {
            (this.state.getFilteredTriggerDataStatus !== '' && this.state.getFilteredTriggerDataStatus !== undefined && this.state.getFilteredTriggerDataStatus !== 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.getFilteredTriggerDataStatus}
                    type={'error'}
                    closable
                    onClose={this.onCloseAlert}
                  />
                </Col>
              </Row>
            )
          }
          {
            (this.state.getProductsByPartnerCodeStatus !== '' && this.state.getProductsByPartnerCodeStatus !== undefined && this.state.getProductsByPartnerCodeStatus !== 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.getProductsByPartnerCodeStatus}
                    type={'error'}
                    closable
                    onClose={this.onCloseAlert}
                  />
                </Col>
              </Row>
            )
          }
          <LayoutContent>
            <EditTemplateStyled>
              <Row>
                <EditRuleModal
                  isOpen={isModalEditRuleOpen}
                  data={this.state.selectedRule}
                  onCloseModal={this.closeEditRuleModal}
                  updateRule={this.updateNewRule}
                />
                <AddRuleModal
                  isOpen={isModalAddRuleOpen}
                  data={this.state.selectedRule}
                  onCloseModal={this.closeAddRuleModal}
                  addRule={this.addNewRule}
                />
                <Col>
                  <Button onClick={this.back}>Back</Button>
                </Col>
                <Spin spinning={this.state.submitting}>
                  <Form
                    onSubmit={this.onSubmit}
                    layout={this.state.formLayout}
                    style={{ marginTop: '20px' }}
                    id='addTemplate'
                  >
                    <Row gutter={24}>
                      <Col span={24}>
                        <FormItem label='Event name'>
                          {getFieldDecorator('name', {
                            rules: [
                              { required: true, message: 'Event name can not be empty' }
                            ]
                          })(
                            <Input disabled={this.state.isDisableInput} />
                          )}
                        </FormItem>
                        <FormItem label='Event type'>
                          {getFieldDecorator('trigger_type', {
                            rules: [
                              { required: true, message: 'Event type can not be empty' }
                            ]
                          })(
                            <Select
                              showSearch
                              placeholder={(masterData.trigger_types !== undefined && masterData.trigger_types.length < 1) ? 'List is empty. request admin to add' : 'Select ...'}
                              style={{ width: '100%' }}
                              filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                              onChange={this.handleChangeEvent}
                              disabled={this.state.isDisableInput}
                            >
                              {
                                masterData.trigger_types !== undefined ? masterData.trigger_types.map((value, index) => {
                                  return <Option key={index} value={value.name}>{value.name}</Option>
                                }) : <Option key={1} value={'loading ...'} disabled>Loading ...</Option>
                              }
                            </Select>
                          )}
                        </FormItem>
                        <Spin spinning={this.state.actionGroupLoader}>
                          <FormItem label='Action group'>
                            {getFieldDecorator('action_group', {
                              rules: [
                                { required: true, message: 'Action group can not be empty' }
                              ]
                            })(
                              <Select
                                disabled={dataActionGroup === undefined || this.state.isDisableInput}
                                showSearch
                                placeholder={(dataActionGroup !== undefined && dataActionGroup.length < 1) ? 'List is empty. request admin to add' : 'Select ...'}
                                style={{ width: '100%' }}
                                filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                                onChange={this.handleChangeActionGroup}
                              >
                                {
                                  dataActionGroup !== undefined ? dataActionGroup.map((value, index) => {
                                    return <Option key={index} value={value.name}>{value.name}</Option>
                                  }) : <Option key={1} value={'loading ...'} disabled>Loading ...</Option>
                                }
                              </Select>
                            )}
                          </FormItem>
                        </Spin>
                        <FormItem label='Partner'>
                          {getFieldDecorator('partner_code', {
                            rules: [
                              { required: true, message: 'Partner code can not be empty' }
                            ]
                          })(
                            <Select
                              disabled={this.state.actionGroup === undefined || this.state.isDisableInput}
                              showSearch
                              placeholder='Select ...'
                              style={{ width: '100%' }}
                              filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                              onChange={this.handleChangePartner}
                            >
                              {
                                partners !== undefined ? partners.map((value, index) => {
                                  return <Option key={index} value={value.code}>{value.name}</Option>
                                }) : <Option key={1} value={'loading ...'} disabled>Loading ...</Option>
                              }
                            </Select>
                          )}
                        </FormItem>
                        <Spin spinning={this.state.loaderProduct}>
                          <FormItem label='Product'>
                            {getFieldDecorator('product_key', {
                              rules: [
                                { required: true, message: 'Product key can not be empty' }
                              ]
                            })(
                              <Select
                                disabled={this.state.partnerValue === undefined || this.state.isDisableInput}
                                showSearch
                                placeholder='Select ...'
                                style={{ width: '100%' }}
                                filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                                onChange={this.handleChangeProduct}
                              >
                                {
                                  dataProducts !== undefined ? dataProducts.products.map((value, index) => {
                                    return <Option key={index} value={value.name}>{value.name}</Option>
                                  }) : <Option key={1} value={'loading ...'} disabled>Loading ...</Option>
                                }
                              </Select>
                            )}
                          </FormItem>
                        </Spin>
                        <FormItem label='Template'>
                          {getFieldDecorator('template_code', {
                            rules: []
                          })(
                            <Select
                              showSearch
                              placeholder='Select ...'
                              style={{ width: '100%' }}
                              filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                              disabled={this.state.isDisableInput}
                            >
                              {
                                dataTemplates !== undefined ? dataTemplates.map((value, index) => {
                                  return <Option key={index} value={value.code}>{value.description}</Option>
                                }) : <Option key={1} value={'loading ...'} disabled>Loading ...</Option>
                              }
                            </Select>
                          )}
                        </FormItem>
                        <FormItem label='Weight'>
                          {getFieldDecorator('weight', {
                            rules: [
                              { required: true, message: 'Weight code can not be empty' }
                            ]
                          })(
                            <Input disabled={this.state.isDisableInput} />
                          )}
                        </FormItem>
                        <FormItem label='Fixed recipients bcc'>
                          {getFieldDecorator('fixed_recipients_bcc', {
                            initialValue: this.state.fixed_recipients_bcc,
                            rules: [{
                              required: false, message: 'Please input your Fixed recipients bcc!'
                            }]
                          })(
                            <TagsInput
                              onChange={e => this.handleChangeTags(e, 'fixed_recipients_bcc')}
                              inputProps={{
                                placeholder: 'Input email'
                              }}
                              validationRegex={/^[^@\s]+@[^@\s]+\.[^@\s]+$/}
                              onlyUnique
                            />
                          )}
                        </FormItem>
                        <FormItem label='Fixed recipients cc'>
                          {getFieldDecorator('fixed_recipients_cc', {
                            initialValue: this.state.fixed_recipients_cc,
                            rules: [{
                              required: false, message: 'Please input your Fixed recipients cc!'
                            }]
                          })(
                            <TagsInput
                              onChange={e => this.handleChangeTags(e, 'fixed_recipients_cc')}
                              inputProps={{
                                placeholder: 'Input email'
                              }}
                              validationRegex={/^[^@\s]+@[^@\s]+\.[^@\s]+$/}
                              onlyUnique
                            />
                          )}
                        </FormItem>
                        <FormItem label='Fixed recipients to'>
                          {getFieldDecorator('fixed_recipients_to', {
                            initialValue: this.state.fixed_recipients_to,
                            rules: [{
                              required: false, message: 'Please input your Fixed Fixed recipients to!'
                            }]
                          })(
                            <TagsInput
                              onChange={e => this.handleChangeTags(e, 'fixed_recipients_to')}
                              inputProps={{
                                placeholder: 'Input email'
                              }}
                              validationRegex={/^[^@\s]+@[^@\s]+\.[^@\s]+$/}
                              onlyUnique
                            />
                          )}
                        </FormItem>
                        <FormItem label='Reply To'>
                          {getFieldDecorator('reply_to', {
                            initialValue: this.state.reply_to,
                            rules: [
                              {
                                type: 'email',
                                required: false,
                                message: 'Please input your Reply To email correctly!'
                              }]
                          })(
                            <Input className='bigInput' />
                          )}
                        </FormItem>
                        <FormItem label='Is Internal'>
                          {getFieldDecorator('is_internal', {
                            initialValue: false
                          })(
                            <Select>
                              <Option key='No' value={false}>No</Option>
                              <Option key='Yes' value>Yes</Option>
                            </Select>
                          )}
                        </FormItem>
                      </Col>
                    </Row>
                    <Row>
                      <Col>
                        <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                          <h4 style={{ marginTop: '30px', marginBottom: '-10px' }}>Current rule</h4>
                          {
                            !this.state.isDisableInput && (
                              <Button
                                type='primary'
                                style={{ marginTop: '25px', marginBottom: '-10px' }}
                                onClick={this.addRule}
                              >
                                <i className='fa fa-plus' aria-hidden='true' />&nbsp;
                                                          Add new rule
                              </Button>
                            )
                          }

                        </div>
                        <TableWrapper
                          pagination={false}
                          columns={columnsExpression}
                          bordered
                          loading={this.state.loadingTableTrigger}
                          rowKey={record => record.index}
                          dataSource={masterExpression}
                          className='isoSearchableTable'
                        />
                      </Col>
                    </Row>
                    <Row>
                      <Col>
                        <TableWrapper
                          pagination={false}
                          columns={columns}
                          bordered
                          loading={this.state.loadingTableTrigger}
                          rowKey={record => record.id}
                          dataSource={dataFilteredTrigger}
                          className='isoSearchableTable'
                        />
                      </Col>
                    </Row>
                  </Form>
                </Spin>
                <Col span={24}>
                  <div style={{ textAlign: 'right', marginTop: '20px' }}>
                    <Button
                      key='submit'
                      type='primary'
                      form='addTemplate'
                      htmlType='submit'
                      loading={submitting}
                      style={{ marginLeft: '10px' }}
                    >
                      Submit
                    </Button>
                  </div>
                </Col>
              </Row>
            </EditTemplateStyled>
          </LayoutContent>
        </LayoutContentWrapper>
      </div>
    )
  }
}

const WrappedForm = Form.create({})(AddTemplate)

export default connect(
  state => ({
    Notifications: state.Notifications,
    Policy: state.Insurance
  }),
  {
    getMasterData,
    updateTemplate,
    resetNotificationCore,
    closeViewBodyHtml,
    addTemplate,
    getActionGroup,
    getProducts,
    getPartners,
    getFilterTriggeredData,
    getTemplates,
    addTrigger,
    resetFilteredData,
    getProduct
  }
)(WrappedForm)
